  'chat.workStatus.telemetry.responseSpeed': 'Ответ',
  'chat.workStatus.telemetry.responseSpeedDescription': 'Как быстро пришёл итоговый текст. Не учитывает начальное ожидание, рассуждение и предыдущие вызовы инструментов. Это оценка по временным меткам текста, а не измерение скорости провайдера.',
  'chat.workStatus.telemetry.speed': 'Весь ход',
  'chat.workStatus.telemetry.elapsed': 'Длительность',
  'chat.workStatus.telemetry.elapsedDescription': 'Реальное время от первого сообщения пользователя до финального ответа ассистента. Включает ожидание модели, выполнение инструментов, сжатие контекста и другие промежутки.',
  'chat.workStatus.telemetry.llmDuration': 'Время модели',
  'chat.workStatus.telemetry.llmDurationDescription': 'Время, затраченное на все шаги модели, включая ожидание ответов. Время выполнения инструментов исключено. Это не только время генерации текста.',
  'chat.workStatus.telemetry.toolDuration': 'Инструменты',
  'chat.workStatus.telemetry.toolDurationDescription': 'Время выполнения инструментов, включая неудачные вызовы. Инструменты, работающие одновременно, считаются один раз, а не суммируются.',
  'chat.workStatus.telemetry.ttft': 'Средний TTFT',
  'chat.workStatus.telemetry.ttftDescription': 'Среднее ожидание до начала первого текста или рассуждения на каждом шаге модели. Скрыто, если у шага нет начала после создания, что часто бывает у шагов только с инструментами и у частей с меткой времени создания.',
  'chat.workStatus.telemetry.firstOutput': 'Первый вывод',
  'chat.workStatus.telemetry.firstOutputDescription': 'Среднее ожидание от начала каждого шага модели до того, как модель что-либо отправит: текст, рассуждение или вызов инструмента. В отличие от TTFT, шаги, начинающиеся с вызова инструмента, тоже учитываются. Скрыто для шагов из OpenCode старше 2.3.0.',
  'chat.workStatus.telemetry.steps': 'Шаги',
  'chat.workStatus.telemetry.stepsDescription': 'Сколько раз модель вызывалась для этого запроса. Чтение результатов инструментов и решение, что делать дальше, обычно требуют ещё одного шага.',
  'chat.workStatus.telemetry.tokens': 'Токены',
  'chat.workStatus.telemetry.tokens.inOut': '{input} ↑ · {output} ↓',
  'chat.workStatus.telemetry.speedDescription': 'Сгенерированные токены за все шаги, включая рассуждение, делённые на время без выполнения инструментов. Ожидание модели всё равно учитывается, поэтому множество коротких вызовов инструментов может снизить это значение.',
  'chat.workStatus.telemetry.tokensDescription': '↑ Входные токены без кэшированных: {input}. ↓ Сгенерированные токены: {output} на текст и вызовы инструментов, плюс {reasoning} на рассуждения. Итоги охватывают все шаги этого запроса.',
  'chat.workStatus.telemetry.cacheHit': 'Кэш',
  'chat.workStatus.telemetry.cacheHitDescription': 'Доля входных токенов, повторно использованных из кэша запросов на всех шагах. Повторное использование контекста может снизить стоимость и ожидание, но это не оценка скорости.',
  'chat.workStatus.telemetry.cost': 'Стоимость',
  'chat.workStatus.telemetry.costDescription': 'Стоимость, которую провайдер сообщил по всем шагам модели для этого запроса, в долларах США. Не включает отдельные сессии субагентов. Ноль может означать бесплатную модель или провайдера, который не сообщает о платежах.',
